1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser, assertNotImpersonating } from "./auth";
8	import {
9	  registrarConfigured,
10	  checkDomains,
11	  registerDomain,
12	  renewDomain,
13	  domainInfo,
14	  listRecords,
15	  addRecord,
16	  deleteRecord,
17	  type RegistrantContact,
18	} from "./registrar";
19	import { domainTerm, domainTermPriceCents } from "./billing-terms";
20	import { debitWallet, InsufficientBalanceError } from "./wallet";
21	import { getSettingBool } from "./settings";
22	import { emailVerificationError } from "./email-verification";
23	
24	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
25	
26	/* ------------------------------------------------------------------ *
27	 * Idempotency helpers
28	 *
29	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
30	 * user+domain. Catches the double-click / impatient-retry case immediately and
31	 * keeps two concurrent requests from both reaching the registrar. Best-effort
32	 * only — it does not survive a restart or span multiple app instances.
33	 *
34	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
35	 * charge+create runs in one `$transaction`, so a duplicate can never both take
36	 * money and create a second row. Renewal is guarded by an in-transaction expiry
37	 * re-check (charge and expiry advance together atomically).
38	 * ------------------------------------------------------------------ */
39	
40	const SUBMIT_GUARD_MS = 120_000;
41	const inFlightSubmits = new Map<string, number>();
42	
43	function beginSubmit(key: string): boolean {
44	  const now = Date.now();
45	  const heldUntil = inFlightSubmits.get(key);
46	  if (heldUntil !== undefined && heldUntil > now) return false;
47	  if (inFlightSubmits.size > 2000) {
48	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
49	  }
50	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
51	  return true;
52	}
53	
54	function endSubmit(key: string): void {
55	  inFlightSubmits.delete(key);
56	}
57	
58	class DuplicateDomainError extends Error {
59	  constructor() {
60	    super("DUPLICATE_DOMAIN");
61	    this.name = "DuplicateDomainError";
62	  }
63	}
64	
65	const isUniqueConflict = (e: any) => e?.code === "P2002";
66	
67	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
68	
69	/**
70	 * After a registrar call fails or times out we must NOT assume the registration
71	 * did not happen — name.com may well have taken the order. Ask the registrar
72	 * before touching the customer's money:
73	 *  - the domain is in our reseller account  -> registered (keep the charge)
74	 *  - the domain is still purchasable        -> not registered (safe to refund)
75	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
76	 */
77	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
78	  try {
79	    const info = await domainInfo(domain);
80	    return { state: "registered", expires: info.expires };
81	  } catch {
82	    /* not in our account, or the API is unhappy — fall through to availability */
83	  }
84	  try {
85	    const [check] = await checkDomains([domain]);
86	    if (check?.available === true) return { state: "not-registered" };
87	  } catch {
88	    /* registrar unreachable */
89	  }
90	  return { state: "unknown" };
91	}
92	
93	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
94	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
95	  // asset from a registrar in the customer's name, with registrant contact details
96	  // taken from this form. `submitTransferIn` — the same product, the same money —
97	  // has carried this guard since it was written; registration and renewal never did.
98	  await assertNotImpersonating();
99	  const user = await requireUser();
100	  // Purchase gate: an unverified address means we cannot reach the person we
101	  // are about to charge. See lib/email-verification.ts.
102	  const unverified = await emailVerificationError(user);
103	  if (unverified) return { error: unverified };
104	  // Feature flag: domain registration can be switched off platform-wide.
105	  if (!(await getSettingBool("feature_domains", true))) {
106	    return { error: "Domain registration is currently unavailable." };
107	  }
108	  if (!registrarConfigured()) {
109	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
110	  }
111	  const contactSchema = z.object({
112	    firstName: z.string().min(1).max(60),
113	    lastName: z.string().min(1).max(60),
114	    address1: z.string().min(1).max(120),
115	    city: z.string().min(1).max(60),
116	    stateProvince: z.string().min(1).max(60),
117	    postalCode: z.string().min(1).max(20),
118	    country: z.string().length(2),
119	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
120	    email: z.string().email(),
121	  });
122	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
123	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
124	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
125	
126	  const contactParsed = contactSchema.safeParse({
127	    firstName: formData.get("firstName"),
128	    lastName: formData.get("lastName"),
129	    address1: formData.get("address1"),
130	    city: formData.get("city"),
131	    stateProvince: formData.get("stateProvince"),
132	    postalCode: formData.get("postalCode"),
133	    country: String(formData.get("country") ?? "").toUpperCase(),
134	    phone: formData.get("phone"),
135	    email: formData.get("email"),
136	  });
137	  if (!contactParsed.success) {
138	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
139	  }
140	
141	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
142	  const guardKey = `register:${user.id}:${domain}`;
143	  if (!beginSubmit(guardKey)) {
144	    return { error: "That registration is already being processed — give it a moment before retrying." };
145	  }
146	
147	  try {
148	    const existing = await db.domain.findUnique({ where: { name: domain } });
149	    if (existing) {
150	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
151	      if (existing.status === "PENDING") {
152	        return { error: "You already have a registration in progress for this domain." };
153	      }
154	      return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
155	    }
156	
157	    // Live availability + retail(markup) & cost prices from name.com
158	    let priceCents: number; // retail per year (customer)
159	    let costCents: number; // registrar cost per year (us)
160	    try {
161	      const [check] = await checkDomains([domain]);
162	      if (!check) return { error: "Could not check availability. Try again." };
163	      if (!check.available) return { error: "Domain is not available." };
164	      if (check.premium) return { error: "Premium domains are not supported yet." };
165	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
166	      priceCents = check.priceCents;
167	      costCents = check.costCents;
168	    } catch (e: any) {
169	      return { error: String(e?.message ?? e).slice(0, 200) };
170	    }
171	
172	    const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
173	    const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
174	    if (user.balanceCents < totalCents) {
175	      return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
176	    }
177	
178	    let record;
179	    try {
180	      record = await db.$transaction(async (tx) => {
181	        // Re-check inside the transaction: the availability round-trip above is
182	        // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
183	        // even if this read misses, the create below rolls the whole debit back.
184	        const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
185	        if (dupe) throw new DuplicateDomainError();
186	        await debitWallet(tx, user.id, totalCents);
187	        await tx.walletTransaction.create({
188	          data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
189	        });
190	        return tx.domain.create({
191	          data: { name: domain, userId: user.id, priceCents, costCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
192	        });
193	      });
194	    } catch (e) {
195	      if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
196	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
197	        return { error: "This domain is already being registered — you have not been charged twice." };
198	      }
199	      throw e;
200	    }
201	
202	    try {
203	      const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
204	      const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
205	      await db.domain.update({
206	        where: { id: record.id },
207	        data: {
208	          status: "ACTIVE",
209	          registeredAt: new Date(),
210	          expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
211	        },
212	      });
213	      await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
214	      await db.notification.create({
215	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
216	      });
217	    } catch (e: any) {
218	      const reason = String(e?.message ?? e).slice(0, 400);
219	      // NEVER refund blind: a timeout/5xx often means the order DID go through.
220	      const verdict = await verifyRegistration(domain);
221	
222	      if (verdict.state === "registered") {
223	        // The registration exists — keep the charge and finish the record.
224	        await db.domain.update({
225	          where: { id: record.id },
226	          data: {
227	            status: "ACTIVE",
228	            registeredAt: new Date(),
229	            expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
230	            error: `Recovered after registrar error: ${reason}`.slice(0, 500),
231	          },
232	        });
233	        await db.auditLog.create({
234	          data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
235	        });
236	        await db.notification.create({
237	          data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
238	        });
239	        redirect(`/dashboard/domains/${record.id}`);
240	      }
241	
242	      if (verdict.state === "not-registered") {
243	        // Confirmed still available at the registrar — refunding is safe.
244	        await db.$transaction([
245	          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
246	          db.walletTransaction.create({
247	            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
248	          }),
249	          db.domain.update({
250	            where: { id: record.id },
251	            data: { status: "FAILED", error: reason.slice(0, 500) },
252	          }),
253	        ]);
254	        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
255	      }
256	
257	      // Unknown: leave PENDING and charged, flag for manual review. Refunding
258	      // here risks giving away a domain we actually paid the registrar for.
259	      await db.domain.update({
260	        where: { id: record.id },
261	        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
262	      });
263	      await db.auditLog.create({
264	        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
265	      });
266	      await db.notification.create({
267	        data: {
268	          userId: user.id,
269	          title: `Domain ${domain} needs review`,
270	          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
271	          href: `/dashboard/domains/${record.id}`,
272	        },
273	      });
274	      return {
275	        error:
276	          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
277	          `It is marked for review — do not retry, you will not be charged twice.`,
278	      };
279	    }
280	    redirect(`/dashboard/domains/${record.id}`);
281	  } finally {
282	    endSubmit(guardKey);
283	  }
284	}
285	
286	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
287	const RENEW_SLACK_MS = 30 * 86400_000;
288	
289	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
290	  // Spend path: a manual renewal debits the wallet and spends at the registrar.
291	  // See purchaseDomain above.
292	  await assertNotImpersonating();
293	  const user = await requireUser();
294	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
295	  // renewal runs in the worker and does not come through here, so no existing
296	  // domain can lapse because of this check.
297	  const unverifiedRenew = await emailVerificationError(user);
298	  if (unverifiedRenew) return { error: unverifiedRenew };
299	  const domain = await db.domain.findUnique({ where: { id: domainId } });
300	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
301	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
302	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
303	
304	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
305	  const guardKey = `renew:${domain.userId}:${domain.name}`;
306	  if (!beginSubmit(guardKey)) {
307	    return { error: "A renewal for this domain is already in progress." };
308	  }
309	
310	  try {
311	    const dTerm = domainTerm(domain.termYears);
312	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
313	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
314	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
315	
316	    const dbExpiry = domain.expiresAt ?? null;
317	
318	    // Idempotency: charge and expiry advance together in one transaction below,
319	    // so if the registrar expiry is already ahead of ours a previous attempt
320	    // renewed but never got charged/recorded. Adopt that renewal instead of
321	    // buying a second year.
322	    let registrarExpiry: Date | undefined;
323	    try {
324	      registrarExpiry = (await domainInfo(domain.name)).expires;
325	    } catch {
326	      /* non-fatal: fall through to a normal renew */
327	    }
328	    const alreadyRenewed =
329	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
330	
331	    if (!alreadyRenewed) {
332	      try {
333	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
334	      } catch (e: any) {
335	        // The registrar call is the FIRST thing that happens, before any debit,
336	        // so "you have not been charged" is a fact here, not a hope — and saying
337	        // it stops a customer retrying a renewal they think half-succeeded.
338	        return {
339	          error:
340	            `The registrar refused to renew ${domain.name}: ${String(e?.message ?? e).slice(0, 200)}. ` +
341	            `Nothing has been charged. Wait a few minutes and try again; if it keeps failing, contact support with this message.`,
342	        };
343	      }
344	      registrarExpiry = await domainInfo(domain.name)
345	        .then((i) => i.expires)
346	        .catch(() => undefined);
347	    }
348	
349	    const targetExpiry =
350	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
351	
352	    try {
353	      const charged = await db.$transaction(async (tx) => {
354	        // Re-read under the transaction: if a concurrent request already advanced
355	        // the expiry it also already took the money — do not charge again.
356	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
357	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
358	          return false;
359	        }
360	        await debitWallet(tx, domain.userId, renewCents);
361	        await tx.walletTransaction.create({
362	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
363	        });
364	        await tx.domain.update({
365	          where: { id: domainId },
366	          data: { expiresAt: targetExpiry, status: "ACTIVE" },
367	        });
368	        return true;
369	      });
370	      if (!charged) {
371	        revalidatePath(`/dashboard/domains/${domainId}`);
372	        return {};
373	      }
374	    } catch (e) {
375	      if (e instanceof InsufficientBalanceError) {
376	        // The registrar renewal already succeeded — flag the uncollected charge
377	        // instead of silently swallowing it.
378	        await db.auditLog
379	          .create({
380	            data: {
381	              userId: domain.userId,
382	              action: "domain.renew.uncharged",
383	              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
384	            },
385	          })
386	          .catch(() => {});
387	        return { error: "Insufficient balance." };
388	      }
389	      throw e;
390	    }
391	    revalidatePath(`/dashboard/domains/${domainId}`);
392	    return {};
393	  } finally {
394	    endSubmit(guardKey);
395	  }
396	}
