398	export async function toggleDomainAutoRenew(domainId: string) {
399	  const user = await requireUser();
400	  const domain = await db.domain.findUnique({ where: { id: domainId } });
401	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
402	  await db.domain.update({ where: { id: domainId }, data: { autoRenew: !domain.autoRenew } });
403	  revalidatePath(`/dashboard/domains/${domainId}`);
404	}
