406	// ---------- DNS management ----------
407	
408	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
409	
410	async function ownedDomain(domainId: string) {
411	  const user = await requireUser();
412	  const domain = await db.domain.findUnique({ where: { id: domainId } });
413	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
414	  if (domain.status !== "ACTIVE") throw new Error("Domain is not active");
415	  return { user, domain };
416	}
417	
418	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
419	  const domainId = String(formData.get("domainId") ?? "");
420	  let ctx;
421	  try {
422	    ctx = await ownedDomain(domainId);
423	  } catch (e: any) {
424	    return { error: e.message };
425	  }
426	  const parsed = z
427	    .object({
428	      name: z.string().max(120).default(""),
429	      type: z.enum(RECORD_TYPES),
430	      address: z.string().min(1).max(500),
431	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
432	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
433	    })
434	    .safeParse({
435	      name: formData.get("name") ?? "",
436	      type: formData.get("type"),
437	      address: formData.get("address"),
438	      ttl: formData.get("ttl") || 300,
439	      mxPref: formData.get("mxPref") || undefined,
440	    });
441	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
442	
443	  // "@" or blank => apex (name.com uses empty host for apex)
444	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
445	  try {
446	    await addRecord(ctx.domain.name, {
447	      host,
448	      type: parsed.data.type,
449	      answer: parsed.data.address,
450	      ttl: parsed.data.ttl,
451	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
452	    });
453	  } catch (e: any) {
454	    // Say what the provider said AND what to do about it. A bare registrar
455	    // string ("422 Unprocessable Entity") tells a customer nothing they can act
456	    // on; this product's standard is that an error explains both halves.
457	    return {
458	      error:
459	        `Your DNS provider refused this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
460	        `Check the value matches the record type (an A record needs an IPv4 address, a CNAME needs a hostname), ` +
461	        `then try again. Nothing was changed.`,
462	    };
463	  }
464	  revalidatePath(`/dashboard/domains/${domainId}`);
465	  return {};
466	}
467	
468	export async function deleteDnsRecord(
469	  domainId: string,
470	  record: { name: string; type: string; address: string }
471	): Promise<{ error?: string }> {
472	  let ctx;
473	  try {
474	    ctx = await ownedDomain(domainId);
475	  } catch (e: any) {
476	    return { error: e.message };
477	  }
478	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
479	  try {
480	    const recs = await listRecords(ctx.domain.name);
481	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
482	    if (!match) return { error: "Record not found (it may have already been removed). Refresh the page to see the current records." };
483	    await deleteRecord(ctx.domain.name, match.id);
484	  } catch (e: any) {
485	    return {
486	      error:
487	        `Your DNS provider refused to remove this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
488	        `The record is still in place — refresh the page and try again in a moment.`,
489	    };
490	  }
491	  revalidatePath(`/dashboard/domains/${domainId}`);
492	  return {};
493	}
494	
495	/**
496	 * One-click: point apex + www at the platform's public IP.
497	 *
498	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
499	 * only then add the replacements — so a registrar hiccup, a rate limit or a
500	 * network blip in between took the domain DARK and left it that way, with an
501	 * error message that did not say the old records were already gone. That is the
502	 * "six domains dark while the run scored 4/4" failure shape: destructive work
503	 * done first, on the assumption the constructive half cannot fail.
504	 *
505	 * The new order is also idempotent — an A record already pointing at `ip` is
506	 * kept rather than churned — so clicking twice is free, and a half-finished run
507	 * can simply be retried.
508	 */
509	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
510	  let ctx;
511	  try {
512	    ctx = await ownedDomain(domainId);
513	  } catch (e: any) {
514	    return { error: e.message };
515	  }
516	  const ip = process.env.PUBLIC_IP;
517	  if (!ip) {
518	    return {
519	      error:
