59	/* ------------------------------------------------------------------ *
60	 * Nameservers
61	 * ------------------------------------------------------------------ */
62	
63	export type NameserverResult = {
64	  error?: string;
65	  nameservers?: string[];
66	  registrarHit?: boolean;
67	  note?: string;
68	};
69	
70	/**
71	 * Persist custom nameservers on the Domain and, when the domain is ACTIVE
72	 * and the registrar is configured, push them to name.com. Two or more
73	 * valid hostnames are required for a registrar update; an empty list clears
74	 * the override locally (name.com default NS remain untouched).
75	 */
76	export async function updateNameservers(
77	  domainId: string,
78	  nameservers: string[]
79	): Promise<NameserverResult> {
80	  const { user, domain } = await ownedDomain(domainId);
81	
82	  const cleaned = (nameservers ?? [])
83	    .map((n) => n.trim().toLowerCase().replace(/\.$/, ""))
84	    .filter(Boolean);
85	  const unique = [...new Set(cleaned)];
86	
87	  for (const ns of unique) {
88	    if (!HOST_RE.test(ns)) return { error: `Invalid nameserver hostname: ${ns}` };
89	  }
90	  if (unique.length > 13) return { error: "At most 13 nameservers are allowed." };
91	  if (unique.length === 1) return { error: "Provide at least two nameservers." };
92	
93	  let registrarHit = false;
94	  let note: string | undefined;
95	
96	  if (unique.length >= 2) {
97	    if (domain.status === "ACTIVE" && registrarConfigured()) {
98	      try {
99	        await nc("POST", `/v4/domains/${encodeURIComponent(domain.name)}:setNameservers`, {
100	          nameservers: unique,
101	        });
102	        registrarHit = true;
103	      } catch (e) {
104	        return { error: `Registrar rejected the update: ${errMsg(e)}` };
105	      }
106	    } else {
107	      note =
108	        "Saved. These will be applied at the registrar once the domain is active and the registrar is configured.";
109	    }
110	  }
111	
112	  await db.domain.update({ where: { id: domainId }, data: { nameservers: unique } });
113	  await db.auditLog.create({
114	    data: {
115	      userId: user.id,
116	      action: "domain.nameservers",
117	      detail: `${domainId} -> [${unique.join(", ")}]${registrarHit ? " (registrar)" : ""}`,
118	    },
119	  });
120	  revalidatePath(`/dashboard/domains/${domainId}`);
121	  return { nameservers: unique, registrarHit, note };
122	}
