76	/** Per-user throttle. Returns an error string when the caller should back off. */
77	function throttle(userId: string, op: string, max: number): string | null {
78	  const rl = checkRateLimit(`files:${op}:${userId}`, { max, windowMs: 60_000 });
79	  if (!rl.ok) return `Too many requests — slow down and retry in ${rl.retryAfterSec}s.`;
80	  return null;
81	}
