83	function toMode(mode: number | null): string | null {
84	  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
85	}
86	
87	function entryOut(e: SftpEntry): FileEntry {
88	  return {
89	    name: e.name,
90	    isDirectory: e.isDirectory,
91	    size: e.size,
92	    modifiedMs: e.modifiedMs,
93	    mode: toMode(e.mode),
94	  };
95	}
