97	/** Map an internal error to a safe, user-facing message. */
98	function safeError(err: unknown): string {
99	  const msg = err instanceof Error ? err.message : String(err);
100	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
101	  // Path/traversal/size messages from lib/sftp are already user-safe.
102	  if (
103	    /traversal|absolute|too long|too large|Invalid|No such|Not a (file|directory)|already exists|reachable|root password|is a directory/i.test(
104	      msg
105	    )
106	  ) {
107	    return msg;
108	  }
109	  // Anything else (connection/protocol errors) — keep it generic.
110	  return "Could not reach the server's filesystem. Please try again shortly.";
111	}
