40	function throttle(userId: string, op: string, max: number): string | null {
41	  const rl = checkRateLimit(`sites:${op}:${userId}`, { max, windowMs: 60_000 });
42	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
