53	/**
54	 * Load a Site and prove the caller owns it. `requireUser()` establishes identity;
55	 * the `userId` check is the ownership proof. This is the single choke point every
56	 * mutating action goes through — there is no path to another user's Site.
57	 */
58	async function ownedSite(id: string) {
59	  const user = await requireUser();
60	  const site = await db.site.findUnique({ where: { id: String(id) } });
61	  if (!site) throw new Error("Not found");
62	  if (site.userId !== user.id) throw new Error("Forbidden");
