66	function rowOut(s: {
67	  id: string;
68	  name: string;
69	  slug: string;
70	  status: string;
71	  templateKey: string | null;
72	  publishedAt: Date | null;
73	  error: string | null;
74	  updatedAt: Date;
75	}): SiteRow {
76	  return {
77	    id: s.id,
78	    name: s.name,
79	    slug: s.slug,
80	    status: s.status,
81	    templateKey: s.templateKey,
82	    publishedAt: s.publishedAt ? s.publishedAt.toISOString() : null,
83	    error: s.error,
84	    updatedAt: s.updatedAt.toISOString(),
85	  };
