193	 * Persist the editor's working document as the site's draft. The client-supplied
194	 * document is validated with `isSiteDocument` before it is stored — never trust
195	 * the shape of anything that came over the wire.
196	 */
197	export async function saveDraft(id: string, document: unknown): Promise<Result> {
198	  try {
199	    const { user, site } = await ownedSite(id);
200	    const limited = throttle(user.id, "save", 60);
201	    if (limited) return { ok: false, error: limited };
202	    if (!isSiteDocument(document)) {
203	      return { ok: false, error: "The editor document is malformed and was not saved." };
204	    }
205	    // Cap the stored payload so a runaway document can't wedge the DB / publish.
206	    const size = JSON.stringify(document).length;
