315	    await db.site.delete({ where: { id: site.id } });
316	    await db.auditLog.create({
317	      data: { userId: user.id, action: "site.delete", detail: `${site.name} (${site.slug})` },
318	    });
319	    revalidatePath("/dashboard/sites");
320	    return { ok: true };
321	  } catch (err) {
322	    return { ok: false, error: safeError(err) };
323	  }
324	}
