91	  // A rollback rewinds the VM's disk. The worker can only do that against a real
92	  // VM in a steady state — the same precondition createSnapshot already enforced.
93	  // Without it we accepted the request, said nothing, and let the job fail in the
94	  // worker while the customer believed their server was being restored.
95	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
96	    return { error: "Server must be running or stopped to roll back to a snapshot." };
97	  }
98	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name: clean });
99	  if (!res.error) {
100	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${clean}` } });
101	    revalidatePath(`/dashboard/servers/${serverId}`);
102	  }
103	  return res;
104	}
