1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	
7	async function ownedServer(serverId: string) {
8	  const user = await requireUser();
9	  const server = await db.server.findUnique({ where: { id: serverId } });
10	  if (!server) throw new Error("Not found");
11	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
12	  return { user, server };
13	}
